import numpy as np
from PIL import Image
im=np.array(Image.open('/app/target.png').convert('L')); m=im<80
for mod in ['skimage.morphology','cv2']:
 try:
  if mod.startswith('skimage'):
   from skimage.morphology import medial_axis
   sk,d=medial_axis(m,return_distance=True,random_state=0)
   w=2*d[sk]*.22186
   print('medial widths mm quantiles',np.percentile(w,[5,10,25,50,75,90,95,99]),'n',len(w))
  else:
   import cv2; print('cv2',cv2.__version__)
 except Exception as e: print(mod,e)
# practice marks thickness bboxes
for name in ['practice_cam_test_depths.png']:
 a=np.array(Image.open('/app/'+name).convert('L'))
 m=a<60
 # connected components bounding box and pixel area
 try:
  from scipy.ndimage import label
  lab,n=label(m)
  for i in range(1,n+1):
   yy,xx=np.where(lab==i)
   if len(xx)>10:
    print(name,i,len(xx),(xx.min(),yy.min(),xx.max(),yy.max()),'row median span',np.median([np.sum(m[y]) for y in range(yy.min(),yy.max()+1)]))
 except Exception as e: print(e)
PY

python - <<'PY'
import numpy as np
from PIL import Image
m=np.array(Image.open('/app/target.png').convert('L'))<100
for v in [260,280,300,330,360,380,400,470,500,550,600,650,700,740,770]:
 # component windows around left/right vertical centers and report black run containing x
 vals=[]
 for c in [376,593]:
  xs=np.where(m[v])[0]; around=xs[(xs>c-100)&(xs<c+100)]
  if len(around):
   # runs in around
   runs=[]; s=pr=around[0]
   for x in around[1:]:
    if x>pr+1:runs.append((s,pr));s=x
    pr=x
   runs.append((s,pr));
   run=min(runs,key=lambda z:abs((z[0]+z[1])/2-c)); vals.append((run[1]-run[0]+1,run))
  else: vals.append(None)
 print('v',v,vals)
PY

